import openpyxl
path='/root/output/result.xlsx'
wb=openpyxl.load_workbook(path)
ws=wb['Task']

# validation: check target ranges not None and start with '='
from openpyxl.utils.cell import range_boundaries

def iter_range(a1):
    min_col, min_row, max_col, max_row = range_boundaries(a1)
    for r in range(min_row, max_row+1):
        for c in range(min_col, max_col+1):
            yield (r,c,ws.cell(row=r,column=c).value)

ranges=['H12:L17','H19:L24','H26:L31','H35:L40','H42:L47','H50:L50']
for rg in ranges:
    bad=[]
    for r,c,v in iter_range(rg):
        if v is None:
            bad.append((r,c,'None'))
        elif not (isinstance(v,str) and v.startswith('=')):
            bad.append((r,c,repr(v)))
    print(rg,'bad count',len(bad))
    if bad:
        print(' first few:',bad[:5])

# print a sample of formulas
samples=['H12','L17','H35','L40','H42','H46','H50','L50']
for addr in samples:
    print(addr, ws[addr].value)

wb.close()
